# Extend refinement to see if the system can resolve the residual 2% deviation

class PrecisionRefinementSystem(ReflectiveSystem):
    """Extends ReflectiveSystem to refine closer to the harmonic target."""
    def refine_to_harmonic(self, target_precision=0.0001, max_iterations=50):
        """Iteratively refine until deviation is below the target precision."""
        for i in range(max_iterations):
            for axis_name, axis in self.axes.items():
                deviation, adjustment = axis.reflect()
                if abs(deviation) > target_precision:
                    axis.refine(adjustment)
                else:
                    self.history.append(
                        f"Axis {axis_name} aligned at iteration {i} with mean {axis.state.mean():.5f}"
                    )
            # Check system-wide alignment
            alignment = self.identify_blanks()
            if alignment["Harmonic Alignment"]:
                self.history.append(f"System harmonized at iteration {i} with means {alignment['Means']}")
                break

# Instantiate the precision refinement system
precision_system = PrecisionRefinementSystem()

# Perform precision refinement to test the residual gap
precision_system.refine_to_harmonic(target_precision=0.0001, max_iterations=50)

# Summarize the refined system's final state
precision_refinement_summary = precision_system.summarize_system()
precision_refinement_summary

